    s.title, s.summary, s.org_name, s.org_type, s.domain_lane,
    s.researcher_name, s.researcher_title,
    'investigating', 'grant_db',
    'JST さきがけ 2025年度採択課題 (研究領域: ' || s.area || ')',
    'reviewed'
  from src s
  where not exists (select 1 from seeds x where x.title = s.title)
  returning id, title
)
insert into seed_funding (seed_id, program, program_short, fiscal_year, status, source_url, notes)
select
  i.id,
  'JST 戦略的創造研究推進事業 (さきがけ)',
  'さきがけ2025',
  2025,
  'awarded',
  'https://www.jst.go.jp/kisoken/presto/application/2025/250918/250918presto.pdf',
  '研究領域: ' || s.area
from ins i join src s on s.title = i.title;
